import{_ as i,b as l,c as o,g as d}from"./chunks/framework.86O3EbG5.js";const a=JSON.parse('{"title":"古代汉语","description":"","frontmatter":{"title":"古代汉语","subTitle":"古汉语语法","author":"oasis","date":"2026-10-21T00:00:00.000Z","tags":["读书笔记"]},"headers":[],"relativePath":"articles/books/classical-chinese/4.md","filePath":"articles/books/classical-chinese/4.md"}'),r={name:"articles/books/classical-chinese/4.md"};function n(s,t,e,p,h,g){return l(),o("div",null,[...t[0]||(t[0]=[d('<p>胡安顺教材第五、六单元讲语法（上）（下）；王力通论（七）至（十四）讲判断句、叙述句、词类活用、代词、连词介词、语气词等。课文例句可对照 <a href="/articles/books/classical-chinese/1-2.html">通论语法总表</a>。</p><h2 id="古汉语语法研究简况" tabindex="-1">古汉语语法研究简况</h2><p>马建忠《马氏文通》（1898）用西方语法学框架系统描写汉语，是古汉语语法研究进入现代阶段的里程碑。主要贡献：</p><ol><li>用语法学方法描写汉语。</li><li>确立实词、虚词的词类体系。</li><li>归纳汉语的主要语法结构。</li></ol><h3 id="二十世纪前五十年" tabindex="-1">二十世纪前五十年</h3><p>重要著作：《中等国文典》《中国文法通论》《国文法之研究》《国文法草创》《词诠》《古书虚字集释》《比较文法》《中国文法语文通解》《中国文法要略》《中国文法论》《中国语法理论》《汉语语法论》等。吕叔湘《中国文法要略》影响很大。</p><h3 id="二十世纪后五十年" tabindex="-1">二十世纪后五十年</h3><p>研究队伍扩大，方法更新；范围从文言扩展到近代汉语、方言、汉藏语比较。吕叔湘是近代汉语分析体系的开创者之一。王力《汉语史稿》是语法史研究的开山之作。台湾周法高《中国古代语法》。杨伯峻注释《左传》等书，兼有语法说明。</p><p>研究方向大致三类：</p><ol><li><strong>历时研究</strong>：断代语法与汉语史。起步早、成就突出的如管燮初《殷虚甲骨刻辞的语法研究》《西周金文语法研究》；另有陈梦家、刘世儒、柳士镇，以及杜百胜、志村良治等海外学者的断代著作。</li><li><strong>专书研究</strong>：如杜百胜《诗经语法》、许世瑛《论语二十篇句法研究》、何乐士《左传虚词研究》、向熹《诗经语言研究》、吴福祥《敦煌变文语法研究》等。</li><li><strong>专题研究</strong>：某一词类、句式或方言现象的专题论文与专著。</li></ol><p>研究方法上，材料统计（穷尽式）很常见。注意：统计量大不等于理解准确，结论仍依赖对文献的准确解读。</p><h2 id="名词、动词、形容词、数量词" tabindex="-1">名词、动词、形容词、数量词</h2><h3 id="一、名词" tabindex="-1">一、名词</h3><p>表示人或事物名称的词。作主语、宾语、定语；也可活用为动词、作状语（见词类活用）。</p><p>常见类别：</p><ul><li><strong>普通名物</strong>：天、地、日、月、人、山、水、牛、马</li><li><strong>抽象概念</strong>：仁、义、礼、道、德、阴阳</li><li><strong>方位时间</strong>：上、下、内、外、东、西、南、北、中；今、昔、时、夜、旦、暮</li><li><strong>职官身份</strong>：公、侯、伯、子、男；天子、诸侯、司寇、陪臣</li><li><strong>专名</strong>：秦穆公、齐桓公、城濮、鄢陵</li></ul><blockquote><p>齐侯纳之，以为诸公子之傅（《鲁施氏有二子》）——侯、公子、傅，名词。</p></blockquote><p>上古名词前可加词头“有”，如有夏、有虞、有穷（见 <a href="/articles/books/classical-chinese/2.html">词汇笔记</a> 附加式）。</p><h3 id="二、动词" tabindex="-1">二、动词</h3><p>表示动作、行为、存在、变化或心理活动。《马氏文通》称“动字”。主要作谓语，也可作主语、宾语、定语等。</p><ul><li><strong>动作行为</strong>：攻、伐、杀、见、闻、取、射</li><li><strong>心理活动</strong>：爱、恶、畏、惧、恐、思、恨</li><li><strong>存在变化</strong>：有、无、生、死、存、在</li><li><strong>能愿</strong>：可、能、欲、忍</li></ul><p>与现代汉语不同的是：动词常有<strong>使动用法</strong>，也可直接放在另一动词前作状语（如“趋而避之”一类），详见词类活用。</p><blockquote><p>孟氏之一子之秦，以术干秦王——干：干谒；之：前往（动词“之”≠助词）。</p></blockquote><h3 id="三、形容词" tabindex="-1">三、形容词</h3><p>表示性质、状态。《马氏文通》称“静字”。主要作定语、谓语，也可作主语、宾语、状语、补语。</p><ul><li><strong>性质</strong>：善、良、美、智、愚、强、弱、高、厚、薄</li><li><strong>状态叠音 / 连绵</strong>：依依、灼灼、穆穆、窈窕、参差</li><li><strong>带词尾</strong>：铿尔、沃若、跃如、俨然、恢恢乎（然、如、若、尔、乎为词尾）</li></ul><p>形容词词头看法不一；有人把“其黄”“有炜”中的“其”“有”看作词头。</p><blockquote><p>孟氏父子舍然无愠容——愠：恼怒。</p></blockquote><p>形容词也常有使动、意动用法。</p><h3 id="四、数量词" tabindex="-1">四、数量词</h3><h4 id="_1-数词" tabindex="-1">1. 数词</h4><p>基数、序数、分数、约数、虚数。上古数词可直接修饰名词，中间常不用量词。</p><ul><li><strong>基数</strong>：鲁施氏有二子</li><li><strong>分数</strong>：戍死者固十六七（《史记》，十分之六七）</li><li><strong>虚数</strong>：千万臣而无数（《九方皋相马》，极言其多）</li><li><strong>整数与零数之间加“有（又）”</strong>：十有七年</li></ul><h4 id="_2-量词" tabindex="-1">2. 量词</h4><p>上古量词不发达，先秦名量词、动量词都比后代少。</p><ul><li><strong>名量</strong>：一箪食，一瓢饮；一乘（一车四马）</li><li><strong>动量</strong>：三战三北（数词直接修饰动词）</li></ul><h2 id="代词" tabindex="-1">代词</h2><p>王力通论（十二）重点。分人称、指示、疑问三类；者、所是特殊指示代词。</p><h3 id="一、人称代词" tabindex="-1">一、人称代词</h3><table tabindex="0"><thead><tr><th>人称</th><th>常见形式</th><th>注意</th></tr></thead><tbody><tr><td>第一人称</td><td>吾、我、余、予、朕</td><td>吾多作主语、定语；我作宾语较自由</td></tr><tr><td>第二人称</td><td>汝（女）、尔、若、而、乃</td><td>“子”表敬称，您</td></tr><tr><td>第三人称</td><td>其、之、彼</td><td>其多作定语；之作宾语；上古没有真正等于现代“他”的主语代词</td></tr></tbody></table><blockquote><p>子之年长矣（《九方皋相马》）——子：您。</p></blockquote><h3 id="二、指示代词" tabindex="-1">二、指示代词</h3><ul><li><strong>近指</strong>：此、是、斯、兹</li><li><strong>远指</strong>：彼、夫</li><li><strong>无定 / 他指</strong>：或（有的人）、莫（没有谁）</li></ul><p>上古“是”是指示代词“这”，不是系词。判断句见下文。</p><blockquote><p>是灭亡之道（《鲁施氏有二子》）——是：这。</p></blockquote><h3 id="三、疑问代词" tabindex="-1">三、疑问代词</h3><p>谁、孰、何、奚、安、焉、胡、曷。疑问代词作宾语时常前置（见词序）。</p><blockquote><p>又何马之能知也；焉往而不穷哉</p></blockquote><h3 id="四、者、所" tabindex="-1">四、者、所</h3><ul><li><strong>者字结构</strong>：V / Adj + 者 → “…的人 / 物”（施事）。好学者、唱善者。</li><li><strong>所字结构</strong>：所 + V → “被…的事物”（受事）。所务、所观。</li></ul><p>详解见 <a href="/articles/books/classical-chinese/1-1.html">所字结构</a>。</p><h2 id="副词" tabindex="-1">副词</h2><p>修饰动词、形容词，表示程度、范围、时间、否定、语气、情态、谦敬等。胡安顺分八类，常用如下：</p><h3 id="_1-程度副词" tabindex="-1">1. 程度副词</h3><p>表示程度高：孔、最、甚、殊、颇、尤、至。益、愈表示程度加深，可译为“更加”。</p><blockquote><p>谋夫孔多，是用不集。（《诗经·小雅·小旻》）——孔：很。 庚申，晋弑其君州蒲。称国以弑其君，君恶甚矣。（《穀梁传·成公十八年》）——甚：太、很。 老臣今者殊不欲食。（《战国策·赵策四》）——殊：特别。 绛侯得释，盎颇有力。（《史记·袁盎晁错列传》）——颇：很、相当。 水至清则无鱼，人至察则无徒。（东方朔《答客难》）——至：极。</p></blockquote><p>表示程度轻：少、稍、略、微、差、小、颇，可译为“稍微”“略微”。少在现代汉语里是形容词，表示数量不多；这里是副词。颇也可以表示程度高，见上。</p><blockquote><p>太后之色少解。（《战国策·赵策四》）——少：稍微。 于是项梁乃教籍兵法，籍大喜，略知其意，又不肯竟学。（《史记·项羽本纪》）——略：略微。 色厉而言方，欲有所为，微见风采，党与承其指意而显奏之。莽稽首涕泣，固推让焉。（《汉书·王莽传》）——微：略微。 唯班固著《百官公卿表》，记汉承秦置官本末，讫于王莽，差有条贯。（《后汉书·百官志》）——差：略微。</p></blockquote><h3 id="_2-范围副词" tabindex="-1">2. 范围副词</h3><p>皆、尽、悉、咸、俱、唯（惟）、但、徒、独</p><blockquote><p>臣之子皆下才也</p></blockquote><h3 id="_3-否定副词" tabindex="-1">3. 否定副词</h3><ul><li><strong>不、弗</strong>：一般否定。弗后面动词往往不带宾语。</li><li><strong>毋、勿</strong>：禁止，不要。</li><li><strong>未</strong>：不曾。</li><li><strong>非</strong>：否定判断（“不是”），不是一般的“不”。</li><li><strong>微</strong>：如果没有（常用于假设）。</li></ul><blockquote><p>色物牝牡尚弗能知；非行之谬也</p></blockquote><h3 id="_4-时间副词" tabindex="-1">4. 时间副词</h3><p>既、已、尝、曾、将、且、方、适、曩、向</p><blockquote><p>既反，孟氏之父子叩胸而让施氏</p></blockquote><h3 id="_5-语气-情态副词" tabindex="-1">5. 语气 / 情态副词</h3><p>固、必、乃、即、诚、殆、庶几</p><blockquote><p>是乃其所以千万臣而无数者也——乃：就是。</p></blockquote><h3 id="_6-谦敬副词" tabindex="-1">6. 谦敬副词</h3><p>请、谨、敬、幸、辱、伏惟（多用于对话礼貌）</p><h3 id="_7-指代性副词" tabindex="-1">7. 指代性副词</h3><p>相、见（如“见欺”中见有指代受事的用法，与被动相关）</p><h2 id="介词、连词" tabindex="-1">介词、连词</h2><h3 id="一、介词" tabindex="-1">一、介词</h3><p>引进对象、工具、处所、时间、原因、比较。介宾短语可在动词前，也可后置。</p><table tabindex="0"><thead><tr><th>介词</th><th>主要作用</th><th>例</th></tr></thead><tbody><tr><td>于（於）、乎</td><td>处所、对象、比较、被动施事</td><td>窘于贫；贵乎马</td></tr><tr><td>以</td><td>凭借、工具、原因；亦可表率领</td><td>以术干齐侯</td></tr><tr><td>为（wèi）</td><td>替、给；表原因</td><td>为吾之患</td></tr><tr><td>为（wéi）</td><td>被动“被”</td><td>为天下笑</td></tr><tr><td>与</td><td>和、跟</td><td>所与共担纆薪菜者</td></tr></tbody></table><h3 id="二、连词" tabindex="-1">二、连词</h3><p>连接词、短语或分句。</p><ul><li><strong>而</strong>：承接 / 转折 / 修饰。遂刖之，而还诸鲁；子道与吾同，而功与吾异</li><li><strong>以</strong>：目的、结果，略等于“来 / 以致”。辞赏以正君</li><li><strong>则</strong>：承接、条件。疾病，则曰…</li><li><strong>且、况</strong>：递进</li><li><strong>虽、若、如</strong>：让步、假设。若用仁义治吾国</li><li><strong>故、是故</strong>：因果</li></ul><p>“以”“与”既可作介词，也可作连词，按语法功能判定。</p><h2 id="语气词、叹词、助词" tabindex="-1">语气词、叹词、助词</h2><h3 id="一、语气词" tabindex="-1">一、语气词</h3><h4 id="句末" tabindex="-1">句末</h4><table tabindex="0"><thead><tr><th>语气词</th><th>作用</th><th>例</th></tr></thead><tbody><tr><td>也</td><td>判断、肯定、解释</td><td>果天下之马也</td></tr><tr><td>矣</td><td>已然、将然（动态）</td><td>已得之矣</td></tr><tr><td>乎</td><td>疑问、反问、感叹</td><td>有可以求马者乎</td></tr><tr><td>哉</td><td>感叹、反问</td><td>焉往而不穷哉</td></tr><tr><td>与（欤）、邪（耶）</td><td>疑问</td><td></td></tr><tr><td>耳、尔</td><td>而已，罢了</td><td></td></tr></tbody></table><p>王力：也偏静态确认，矣偏动态变化。</p><h4 id="句首-句中" tabindex="-1">句首 / 句中</h4><p>夫、盖、惟（维）、其（表推测、祈使）</p><blockquote><p>夫尺蠖食黄则其身黄（《景公射出质》）——夫：发语。</p></blockquote><h3 id="二、叹词" tabindex="-1">二、叹词</h3><p>嘻、噫、嗟、呜呼等，独立于句子结构之外。</p><blockquote><p>嘻！先生何病（《原宪居鲁》）</p></blockquote><h3 id="三、助词" tabindex="-1">三、助词</h3><p>结构助词“之”最重要：</p><ol><li>定语标志：诸公子之傅</li><li>取消句子独立性：羡施氏之有；弦章之廉</li><li>宾语前置标志：何马之能知</li><li>凑足音节（衬字）</li></ol><p>词头、词尾（有、言、然、如等）有的语法书归入助词，词汇笔记里按构词讲。</p><h2 id="兼词、固定结构与固定格式" tabindex="-1">兼词、固定结构与固定格式</h2><h3 id="一、兼词" tabindex="-1">一、兼词</h3><p>一字兼两个词的音义。</p><table tabindex="0"><thead><tr><th>兼词</th><th>合音</th><th>例</th></tr></thead><tbody><tr><td>诸</td><td>之 + 于 / 之 + 乎</td><td>还诸鲁</td></tr><tr><td>焉</td><td>于 + 之</td><td>有一焉</td></tr><tr><td>盍</td><td>何 + 不</td><td>盍各言尔志</td></tr><tr><td>叵</td><td>不 + 可</td><td>居心叵测（后起义常用）</td></tr></tbody></table><h3 id="二、固定结构-举例" tabindex="-1">二、固定结构（举例）</h3><ul><li><strong>如何 / 若何 / 奈何</strong>：怎么办</li><li><strong>孰与</strong>：与…比怎么样</li><li><strong>无以 / 有以</strong>：没有用来…的 / 有用来…的</li><li><strong>所以</strong>：用来…的方法；…的原因（≠现代“因此”）</li><li><strong>以为</strong>：认为；以（之）为</li></ul><h3 id="三、固定格式-举例" tabindex="-1">三、固定格式（举例）</h3><ul><li><strong>不亦…乎</strong>：不也是…吗</li><li><strong>何…之有</strong>：有什么…</li><li><strong>唯…是 / 之…</strong>：只…（宾语前置强调）</li><li><strong>……之谓也</strong>：说的就是…</li></ul><h2 id="词类活用" tabindex="-1">词类活用</h2><p>本是甲类词，在句中临时具备乙类词的语法功能。胡安顺、王力都列为阅读关键。</p><h3 id="一、名词、形容词、数词用作动词" tabindex="-1">一、名词、形容词、数词用作动词</h3><ul><li><strong>名词作动词</strong>：遂宫而放之（施加宫刑）；杖藜而应门（拄）；// 履至尊而制六合（登）</li><li><strong>形容词作动词</strong>：正君（使君正，兼使动）；近贼</li><li><strong>数词作动词</strong>：六王毕，四海一（统一）</li></ul><h3 id="二、名词、动词作状语" tabindex="-1">二、名词、动词作状语</h3><p>名词（或动词）放在动词前修饰谓语。常见译法：</p><table tabindex="0"><thead><tr><th>类型</th><th>译法</th><th>例</th></tr></thead><tbody><tr><td>比喻</td><td>像…一样</td><td>蚕食诸侯；云集响应</td></tr><tr><td>处所</td><td>在…</td><td>道听而途说</td></tr><tr><td>工具 / 依据</td><td>用… / 按…</td><td>箕畚运于渤海之尾；义不杀少</td></tr><tr><td>态度</td><td>把…当作</td><td>礼贤下士（礼：以礼）</td></tr></tbody></table><h3 id="三、使动用法" tabindex="-1">三、使动用法</h3><p>主语使宾语产生某动作或状态，客观致使。格式：使宾语怎么样。</p><ol><li><strong>动词使动</strong>：活之 = 使之活；饮诸大夫酒 = 使诸大夫饮</li><li><strong>形容词使动</strong>：富其家、荣其亲、全而归之</li><li><strong>名词使动</strong>：王我 = 使我为王；从左右，皆肘之（用肘撞）</li></ol><h3 id="四、意动用法" tabindex="-1">四、意动用法</h3><p>主语主观上认为宾语怎么样，或把宾语当作什么；客观未必如此。</p><ol><li><strong>形容词意动</strong>：美我 = 以我为美；耻之</li><li><strong>名词意动</strong>：友麋鹿 = 以麋鹿为友；襟三江而带五湖</li></ol><p><strong>辨析</strong>：使动是“使宾语变”；意动是“认为 / 当作”。禄富其家是使动；吾妻之美我者是意动。</p><h2 id="判断句" tabindex="-1">判断句</h2><p>上古汉语判断句一般<strong>不用系词“是”</strong>；“是”为指示代词。判断靠语气词、副词和语序。</p><h3 id="常见格式" tabindex="-1">常见格式</h3><ol><li><strong>……者，……也</strong>：廉颇者，赵之良将也。</li><li><strong>……，……也</strong>（最常见）：臣之子皆下才也；吾弱国也。</li><li><strong>……者，……</strong>：陈涉者，阳城人也。（也偶尔可省）</li><li><strong>……，……者也</strong>：是乃其所以千万臣而无数者也。</li><li><strong>副词加强</strong>：乃 / 即 / 则 / 必……也。若皋之所观，天机也。</li><li><strong>否定判断用“非”</strong>：非行之谬也；贫也，非病也。</li></ol><h3 id="注意" tabindex="-1">注意</h3><ul><li>“为”可表判断（“为天下笑”的“为”是被动介词，另当别论）；“是”作判断系词是后起用法。</li><li>判断句主语和谓语都是名词性成分；翻译时常加“是”。</li></ul><h2 id="被动句" tabindex="-1">被动句</h2><p>被动句：主语是动词的受事。分有形式标志与意念被动两类。王力归纳上古常见四种有标志句式。</p><h3 id="一、有标志的被动句式" tabindex="-1">一、有标志的被动句式</h3><ol><li><strong>于字句</strong>：动词 + 于 + 施事 <blockquote><p>窘于贫；夫赵强而燕弱，而君幸于赵王</p></blockquote></li><li><strong>为字句</strong>：为 + 施事 + 动词 <blockquote><p>身死人手，为天下笑</p></blockquote></li><li><strong>为……所……</strong><blockquote><p>若属皆且为所虏；为秦人积威之所劫</p></blockquote></li><li><strong>见 / 见……于……</strong><blockquote><p>诚恐见欺于王而负赵；未见于众（《景公射出质》）</p></blockquote></li></ol><p>另有“被”字句，先秦少，汉代以后增多。</p><h3 id="二、意念被动" tabindex="-1">二、意念被动</h3><p>无被动标志，靠语义判断主语是受事。</p><blockquote><p>先日所用，今或弃之——所用：被采用的（道术）。过失不掩——过失不被掩盖。</p></blockquote><h2 id="词序" tabindex="-1">词序</h2><p>常规语序：主语—谓语—宾语。变式中最重要的是宾语前置、定语后置。</p><h3 id="一、宾语前置" tabindex="-1">一、宾语前置</h3><p>王力三类（胡安顺同）：</p><ol><li><p><strong>否定句中代词宾语前置</strong></p><p>格式：否定词 + 代词宾语 + 动词</p><blockquote><p>古之人不余欺也（= 不欺余）；莫我知也夫</p></blockquote></li><li><p><strong>疑问代词作宾语前置</strong></p><blockquote><p>焉往（= 往焉）；沛公安在；何马之能知（兼用“之”）</p></blockquote></li><li><p><strong>用“之 / 是”作标志把宾语提前</strong></p><blockquote><p>宋何罪之有；唯利是图；唯马首是瞻</p></blockquote></li></ol><p>谓语前置（主谓倒装）用于感叹、疑问，强调谓语：</p><blockquote><p>败矣，子所使求马者！甚矣，汝之不惠！</p></blockquote><h3 id="二、定语后置" tabindex="-1">二、定语后置</h3><ol><li>中心词 + 之 + 定语 + 者：马之千里者（千里马）</li><li>中心词 + 定语 + 者：求人可使报秦者</li><li>数量定语后置：驾寒牛车一乘（后起义常见）</li></ol><h3 id="三、介宾短语后置" tabindex="-1">三、介宾短语后置</h3><p>于、以、乎构成的介宾常在动词或形容词后，翻译时移到前面。</p><blockquote><p>可告以良马 = 可以良马告之；贵乎马 = 贵于马</p></blockquote><h2 id="参考书" tabindex="-1">参考书</h2><ul><li>王力主编《古代汉语》，中华书局（通论七至十四）</li><li>胡安顺、郭芹纳主编《古代汉语》，中华书局（第五、六单元）</li><li>马建忠《马氏文通》</li><li>吕叔湘《中国文法要略》</li><li>杨伯峻、何乐士《古汉语语法及其发展》</li><li>王力《汉语史稿》（中册，语法史）</li></ul>',147)])])}const c=i(r,[["render",n]]);export{a as __pageData,c as default};
